let catalog={},record=null,saved=null,status=null,editors={},dirty=false,previewHistory=[],editContext=null;
const node=(tag,text)=>{let e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
function message(s,error=false){$('message').textContent=s;$('message').className=error?'error':'';}
async function confirmAction(prompt){return new Promise(resolve=>{const d=node('dialog'),p=node('p',prompt),ok=node('button','ยืนยัน'),cancel=node('button','ยกเลิก');ok.onclick=()=>{d.close();d.remove();resolve(true);};cancel.onclick=()=>{d.close();d.remove();resolve(false);};d.addEventListener('cancel',e=>{e.preventDefault();d.close();d.remove();resolve(false);});d.append(p,cancel,ok);document.body.append(d);d.showModal();});}
function userError(s){let msg=s;for(let [a,b] of Object.entries({'Open this page using Open-Owner-Content.cmd':'กรุณาเปิดหน้านี้ผ่านไฟล์ Open-Owner-Content.cmd','Confirm that these values come from center information':'ติ๊กยืนยันแหล่งข้อมูลจริงก่อนบันทึก','Time-sensitive content requires confirmed validity':'หมวดนี้ต้องยืนยันวันเริ่มมีผลก่อนเผยแพร่','English translation needs review or explicit machine-translation status':'เลือกสถานะคำแปลอังกฤษให้ตรงกับการตรวจจริง','required before publication':'ต้องยืนยันข้อมูลช่องนี้ก่อนเผยแพร่','missing reference':'ไม่พบรายการที่เชื่อม','source needs factual review':'ต้องตรวจข้อมูลจากต้นทางก่อนเผยแพร่','Known validity requires effective_from':'เลือกวันที่เริ่มมีผลด้วย','Unknown validity cannot assert dates':'หากยังไม่ยืนยันช่วงวันที่ ให้ล้างวันที่เริ่มและสิ้นสุด','Stale English review':'ข้อความเปลี่ยนแล้ว ต้องตรวจคำแปลอังกฤษฉบับนี้ใหม่','Stale or withdrawn revision':'มีคนบันทึกฉบับใหม่แล้ว หรือรายการนี้ถูกถอน กรุณาเปิดรายการล่าสุดก่อนแก้','Future replacement must remain a draft until its effective date':'ฉบับใหม่ยังไม่ถึงวันเริ่มใช้ เก็บเป็นร่างไว้ก่อน แล้วเผยแพร่เมื่อถึงวัน เพื่อให้แชทยังอ่านฉบับเดิม','Change note must be text of at most 1000 characters':'เหตุผลที่แก้ไขยาวได้ไม่เกิน 1000 ตัวอักษร'}))msg=msg.split(a).join(b);if(record)for(let f of catalog[record.kind].fields)msg=msg.split(f.key+':').join(f.meaning_th+':');return msg;}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});let x=await r.json();if(!r.ok)throw Error(x.error||r.status);return x;}
async function task(fn){let controls=Array.from(document.querySelectorAll('button,input,select,textarea')).map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);try{await fn();}catch(e){message(userError(e.message),true);}finally{controls.forEach(([e,was])=>{if(e.isConnected)e.disabled=was;});}}
function defaults(s){let t=Array.isArray(s.type)?s.type.find(x=>x!=='null'):s.type;if(s.enum)return s.enum[0];if(t==='object')return Object.fromEntries(Object.entries(s.properties||{}).map(([k,v])=>[k,defaults(v)]));if(t==='array')return [];if(t==='boolean')return false;if(t==='integer')return s.minimum||0;return '';}
function valueEditor(schema,val,refKind=null,key=""){
 let root=node('div'),get;let t=Array.isArray(schema.type)?schema.type.find(x=>x!=='null'):schema.type;
 if(refKind&&t==='string'){let s=node('select');s.append(new Option('เลือกชื่อรายการที่สร้างไว้',''));s.setAttribute('aria-label',SUB_LABELS[key]||'เลือกรายการที่เชื่อม');for(let r of status.records.filter(r=>!r.withdrawn&&(refKind==='*'||r.kind===refKind)))s.append(new Option((r.label||r.record_id)+' ['+r.record_id+']',r.record_id));s.value=val||'';root.append(s);if(s.options.length===1)root.append(node('p','ยังไม่มีรายการให้เลือก กรุณาสร้างหมวดที่เกี่ยวข้องก่อน (ดู “ต้องมีข้อมูลไหนก่อน” ด้านบน)'));get=()=>s.value;}
 else if(schema.enum){let s=node('select');for(let v of schema.enum)s.append(new Option(OPTION_LABELS[v]||v,v));s.value=val??schema.enum[0];root.append(s);get=()=>s.value;}
 else if(t==='object'){
  let children={};for(let [k,sub] of Object.entries(schema.properties||{})){let l=node('label',SUB_LABELS[k]||k);let ed=valueEditor(sub,val?.[k],k==='contact_id'?'contact':null,k);l.append(ed.root);root.append(l);children[k]=ed;}
  root.className='nested';get=()=>Object.fromEntries(Object.entries(children).map(([k,ed])=>[k,ed.get()]));
 }else if(t==='array'){
  let rows=[],holder=node('div'),add=node('button','+ เพิ่มรายการ');add.type='button';add.className='secondary';
  const make=x=>{let row=node('div');row.className='row';let ed=valueEditor(schema.items,x,refKind,key);let del=node('button','ลบแถว');del.className='danger';del.type='button';let item={row,ed};del.onclick=()=>{rows=rows.filter(v=>v!==item);row.remove();dirty=true;};row.append(ed.root,del);rows.push(item);holder.append(row);};
  for(let x of val||[])make(x);add.onclick=()=>{make(defaults(schema.items));dirty=true;};root.append(holder,add);get=()=>rows.map(r=>r.ed.get());
 }else if(t==='boolean'){let s=node('select');s.append(new Option('ใช่ / มี / รองรับ','true'),new Option('ไม่ใช่ / ไม่มี / ไม่รองรับ','false'));s.value=String(val??false);root.append(s);get=()=>s.value==='true';}
 else if(key==='amount_minor'&&t==='integer'){let i=node('input');i.type='text';i.inputMode='decimal';i.setAttribute('aria-label','ราคาเป็นบาท');i.placeholder='เช่น 35 หรือ 35.50';i.value=val===null||val===undefined?'':String(Math.floor(val/100))+'.'+String(val%100).padStart(2,'0');let hint=node('small','กรอกบาท ไม่ต้องคูณ 100 เอง; ทศนิยมได้ไม่เกิน 2 ตำแหน่ง');root.append(i,hint);get=()=>{let raw=i.value.trim();if(!/^(\d+|\d{1,3}(,\d{3})+)(\.\d{1,2})?$/.test(raw))throw Error('ราคา: กรอกจำนวนบาท เช่น 35 หรือ 35.50 (ไม่เกิน 2 ตำแหน่ง)');let [a,b='']=raw.replace(/,/g,'').split('.'),n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n))throw Error('ราคาเกินขอบเขตที่ระบบรองรับ');return n;};}
 else if(key==='weekday'&&t==='integer'){let s=node('select');['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์','อาทิตย์'].forEach((v,i)=>s.append(new Option(v,String(i))));s.value=String(val??0);root.append(s);get=()=>Number(s.value);}
 else if(t==='integer'){let i=node('input');i.type='number';i.step='1';if(schema.minimum!==undefined)i.min=schema.minimum;if(schema.maximum!==undefined)i.max=schema.maximum;i.value=val??'';root.append(i);get=()=>{if(i.value===''||!Number.isInteger(Number(i.value)))throw Error('ต้องกรอกจำนวนเต็ม ห้ามเว้นว่างแล้วตีความเป็น 0');return Number(i.value);};}
 else if(Array.isArray(schema.type)&&schema.type.includes('array')&&schema.type.includes('string')){let i=node('textarea');i.value=JSON.stringify(val??'');root.append(i);get=()=>JSON.parse(i.value);}
 else {let i=node('textarea');i.value=val??'';i.rows=2;i.placeholder=key==='en'?'ยังไม่มีคำแปลให้เว้นว่าง':key==='start'?'เช่น 09:00':key==='end'?'เช่น 12:00':'';root.append(i);get=()=>i.value.trim()===''&&Array.isArray(schema.type)&&schema.type.includes('null')?null:i.value.trim();}
 root.addEventListener('input',()=>dirty=true);root.addEventListener('change',()=>dirty=true);return {root,get};
}
function localTime(v){if(!v)return '';return new Date(new Date(v).getTime()+7*3600000).toISOString().slice(0,16);}
function render(r,revision=null){record=r;saved=revision;dirty=false;editors={};$('welcome').hidden=true;$('editor').hidden=false;$('fields').replaceChildren();$('heading').textContent=OWNER_HELP[r.kind].label;$('rid').value=r.record_id;$('rid').disabled=!!revision;$('alias_th').value=r.aliases.th.join('\n');$('alias_en').value=r.aliases.en.join('\n');$('validity').value=r.validity.state;$('from').value=localTime(r.validity.effective_from);$('until').value=localTime(r.validity.effective_until);$('source_lang').value=r.localization.source_language;$('en_status').value=r.localization.en_status;$('attest').checked=false;
 $('translation_reviewed').checked=false;
 for(let f of catalog[r.kind].fields){let unit=r.fields[f.key];let box=node('div');box.className='field';box.append(node('h3',(f.publish_core?'★ ต้องมี: ':'')+fieldLabel(f,r.kind)));let s=node('select');s.className='status';for(let [v,l] of Object.entries({unknown:'ไม่ทราบ / ยังไม่มีข้อมูล',known:'มีข้อมูลยืนยัน',not_applicable:'ไม่เกี่ยวข้อง',conflicted:'ข้อมูลขัดกัน'}))s.append(new Option(l,v));s.value=unit.status;let ed=valueEditor(f.value_schema,f.key==='amount_minor'?unit.value:(unit.value??defaults(f.value_schema)),f.reference_kind,f.key);ed.root.setAttribute('aria-label',fieldLabel(f,r.kind));box.dataset.field=f.key;s.setAttribute('aria-label','สถานะ: '+fieldLabel(f,r.kind));let h=FIELD_HELP[r.kind][f.key];box.append(node('p',h.hint));let ex=node('details');ex.className='field-example';ex.append(node('summary','ดูตัวอย่างการกรอก: '+fieldLabel(f,r.kind)),(f.key==='amount_minor'?node('p',(h.example/100).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+' บาท — ใส่จำนวนบาทนี้ในช่องราคา'):exampleView(h.example)),node('small','ตัวอย่างสมมุติสำหรับอธิบายช่องกรอก ไม่ใช่ข้อมูลจริงของศูนย์ และไม่ถูกใส่ลงในช่องอัตโนมัติ'));box.append(ex);let note=node('textarea');note.placeholder='หมายเหตุ / ขอบเขต / ข้อมูลที่ยังต้องยืนยัน';note.value=unit.note||'';note.setAttribute('aria-label','หมายเหตุ: '+fieldLabel(f,r.kind));ed.root.hidden=s.value!=='known';s.onchange=()=>{ed.root.hidden=s.value!=='known';dirty=true;};box.append(s,ed.root,note);$('fields').append(box);editors[f.key]={s,ed,note};}
 showGuide(r.kind);updateReadiness();renderEditTools();$('state').textContent=revision?'ฉบับ '+revision.version+' • '+(revision.approved_hash===revision.hash?'อนุมัติแล้ว':'ร่างยังไม่อนุมัติ'):'รายการใหม่ ยังไม่บันทึก';
}
function collect(){let r=structuredClone(record);r.record_id=$('rid').value.trim();r.aliases={th:$('alias_th').value.split('\n').map(x=>x.trim()).filter(Boolean),en:$('alias_en').value.split('\n').map(x=>x.trim()).filter(Boolean)};r.validity={state:$('validity').value,effective_from:$('from').value?$('from').value+':00+07:00':null,effective_until:$('until').value?$('until').value+':00+07:00':null};r.localization={source_language:$('source_lang').value,en_status:$('en_status').value,source_revision_hash:null};for(let [k,x] of Object.entries(editors)){if(x.s.value==='conflicted')throw Error('ข้อมูลขัดกัน: เก็บหลักฐานแยกในฉบับร่าง JSON และตัดสินใจก่อนเผยแพร่');r.fields[k]={status:x.s.value,value:x.s.value==='known'?x.ed.get():null,evidence_refs:[],note:x.note.value||null};}return r;}
async function refresh(){status=await api('/api/status');$('release').textContent=(status.demo?'ฐานทดสอบข้อมูลสมมุติ • ':'')+'รุ่นเผยแพร่: '+(status.active||'ยังไม่มี');drawList();}
function drawList(){let q=$('search').value.toLowerCase();$('list').replaceChildren();for(let r of status.records.filter(r=>r.kind===$('kind').value&&(r.record_id+' '+(r.label||'')).toLowerCase().includes(q))){let b=node('button','✎ แก้ไข: '+(r.label||r.record_id)+' ['+r.record_id+'] • '+(r.withdrawn?'ถอนแล้ว':r.approved_hash===r.hash?'อนุมัติ':'ร่าง')+(status.published_ids.includes(r.record_id)?' • มีฉบับเผยแพร่':''));b.onclick=()=>task(async()=>{if(dirty&&!await confirmAction('มีข้อมูลยังไม่บันทึก ต้องการเปลี่ยนรายการหรือไม่?'))return;await openExisting(r.record_id);});$('list').append(b);}}
$('kind').onchange=()=>task(async()=>{if(dirty&&!await confirmAction('มีข้อมูลที่ยังไม่บันทึก ต้องการเปลี่ยนหมวดและออกจากรายการนี้หรือไม่?')){$('kind').value=record.kind;return;}dirty=false;record=null;saved=null;editContext=null;$('editor').hidden=true;$('welcome').hidden=false;showGuide($('kind').value);drawList();});$('search').oninput=drawList;$('refresh').onclick=()=>task(refresh);
$('new').onclick=()=>task(async()=>{if(dirty&&!await confirmAction('สร้างใหม่โดยออกจากร่างที่ยังไม่บันทึก?'))return;editContext=null;render(await api('/api/template?kind='+$('kind').value));});
$('translate_draft').onclick=()=>task(async()=>{let note=$('change_note').value;let x=await api('/api/translate',{record:collect(),replace_existing:$('translate_replace').checked});render(x.record,saved);$('change_note').value=note;$('translation_reviewed').checked=false;dirty=true;updateReadiness();message('แปลเป็นร่างแล้ว '+x.translated_count+' ช่อง ยังไม่บันทึกหรือเผยแพร่ กรุณาตรวจความหมายแล้วบันทึก');});
$('save').onclick=()=>task(async()=>{let x=await api('/api/save',{record:collect(),expected_version:saved?.version||0,attest:$('attest').checked,translation_reviewed:$('translation_reviewed').checked,change_note:$('change_note').value});await openExisting(x.record_id);await refresh();message('บันทึกร่างแล้ว ยังไม่เปลี่ยนคำตอบในแชท');});
$('approve').onclick=()=>task(async()=>{if(!saved||dirty)throw Error('บันทึกร่างล่าสุดก่อนอนุมัติ');if(!await confirmAction('ยืนยันว่าตรวจเนื้อหา ความสัมพันธ์ ช่วงวันที่ และคำแปลของร่างนี้แล้ว?'))return;await api('/api/approve',{id:saved.record_id,version:saved.version,hash:saved.hash,confirm:true});await openExisting(saved.record_id);await refresh();message('อนุมัติแล้ว ขั้นต่อไปเลือกเผยแพร่');});
$('publish').onclick=()=>task(async()=>{if(!saved||dirty)throw Error('บันทึกและอนุมัติร่างล่าสุดก่อน');if(!await confirmAction('เผยแพร่ร่างที่อนุมัติของรายการนี้ให้แชทบอทอ่าน?'))return;await api('/api/publish',{ids:[saved.record_id],expected_active:status.active,request_key:crypto.randomUUID()});await openExisting(saved.record_id);await refresh();message('เผยแพร่แล้ว คำถามใหม่จะอ่านรุ่นใหม่โดยไม่ต้อง restart');});
$('withdraw').onclick=()=>task(async()=>{if(!saved)throw Error('ยังไม่มีรายการ');if(!await confirmAction('ถอนรายการนี้จากคำตอบ? หากมีรายการอื่นอ้างอิงต้องถอนรายการเหล่านั้นก่อน'))return;await api('/api/withdraw',{id:saved.record_id});await refresh();message('ถอนรายการแล้ว ประวัติยังอยู่');});
$('export').onclick=()=>{try{let blob=new Blob([JSON.stringify(collect(),null,2)],{type:'application/json'});let a=node('a');a.href=URL.createObjectURL(blob);a.download=record.record_id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){message(userError(e.message),true);}};
$('preview').onclick=()=>task(async()=>{let q=$('question').value;let x=await api('/api/preview',{question:q,locale:$('preview_lang').value,history:previewHistory,draft:$('preview_draft').checked});$('answer').textContent=x.answer;$('trace').textContent=JSON.stringify(x.trace,null,2);previewHistory.push({role:'user',content:q},{role:'assistant',content:x.answer,common_read_state:x.trace?.query_plan?{schema_version:1,record_ids:x.trace.query_plan.record_ids||[],requested_fields:x.trace.query_plan.requested_fields||[]}:null});});
for(let id of ['rid','alias_th','alias_en','validity','from','until','source_lang','en_status'])$(id).addEventListener('change',()=>dirty=true);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
task(async()=>{let x=await api('/api/registry');catalog=Object.fromEntries(x.catalog.map(c=>[c.kind,c]));let groups={};for(let c of x.catalog){let h=OWNER_HELP[c.kind];if(!groups[h.group]){let g=node('optgroup');g.label=h.group;$('kind').append(g);groups[h.group]=g;}groups[h.group].append(new Option(h.label,c.kind));}$('kind').value='game';$('identity').textContent='ผู้จัดการข้อมูล: '+x.actor+' • '+x.version;await refresh();showGuide('game');message('พร้อมกรอกข้อมูล • '+x.kinds+' ประเภท');});


function exampleView(v){let root=node('div');root.className='example-values';if(Array.isArray(v)){if(!v.length)root.append(node('p','ไม่เพิ่มรายการ (ใช้ได้เฉพาะเมื่อยืนยันว่าเป็นรายการว่างจริง)'));v.forEach((x,i)=>{let item=node('div');item.append(node('strong','รายการที่ '+(i+1)),exampleView(x));root.append(item);});}else if(v&&typeof v==='object'){for(let [k,x] of Object.entries(v)){let l=node('div');l.append(node('strong',(SUB_LABELS[k]||k)+': '),exampleView(x));root.append(l);}}else root.append(node('span',v===null?'เว้นว่าง':typeof v==='boolean'?(v?'ใช่ / มี / รองรับ':'ไม่ใช่ / ไม่มี / ไม่รองรับ'):OPTION_LABELS[v]||String(v)));return root;}
function showGuide(kind){let h=OWNER_HELP[kind],c=catalog[kind];$('guide').replaceChildren();$('guide').append(node('h2','เลือกหมวดนี้เมื่อไหร่?'),node('h3',h.label),node('p',h.when),node('p','ช่วยตอบคำถาม เช่น “'+h.question+'”'));let box=node('div');box.className='guide-tip';box.append(node('strong','จำง่าย ๆ: '),node('span',h.tip));$('guide').append(box);let before=h.before.filter(k=>k!==kind).map(k=>OWNER_HELP[k].label);$('guide').append(node('p','ต้องมีข้อมูลไหนก่อน: '+(before.length?before.join(' / ')+' (เฉพาะช่องที่ใช้เชื่อม)':'เริ่มกรอกหมวดนี้ได้เลย ไม่ต้องสร้างหมวดอื่นก่อน')));let core=node('ul');for(let f of c.fields.filter(f=>f.publish_core))core.append(node('li',fieldLabel(f,kind)));let det=node('details');det.append(node('summary','ก่อนเผยแพร่ ต้องมีอะไรบ้าง ('+c.fields.filter(f=>f.publish_core).length+' ช่อง)'),core);$('guide').append(det);$('new').textContent='＋ เพิ่ม'+h.label;$('rid').placeholder=kind+'_example';$('form_intro').textContent='เริ่มจากช่อง ★ เลือก “มีข้อมูลยืนยัน” แล้วกรอกตามข้อมูลจริง ช่องที่ยังไม่ทราบเก็บเป็นร่างได้';}
function updateReadiness(){if(!record)return;let needed=catalog[record.kind].fields.filter(f=>f.publish_core);let missing=needed.filter(f=>editors[f.key]?.s.value!=='known');$('readiness').textContent=missing.length?'ยังต้องยืนยัน '+missing.length+' ช่องก่อนเผยแพร่: '+missing.map(f=>fieldLabel(f,record.kind)).join(' / '):'เลือกยืนยันช่องหลักครบแล้ว กรุณาตรวจค่าที่กรอก แหล่งข้อมูล รายการที่เชื่อม และช่วงวันที่ก่อนอนุมัติ';}
$('fields').addEventListener('change',updateReadiness);


async function openExisting(id){let x=await api('/api/edit-context?id='+encodeURIComponent(id));editContext=x;render(x.latest.record,x.latest);}
function renderEditTools(){let editing=!!saved;$('edit_tools').hidden=!editing;$('change_note').value='';$('change_summary').replaceChildren();if(!editing){$('save').textContent='บันทึกฉบับร่าง';return;}$('edit_heading').textContent='✎ แก้ไขข้อมูลเดิม • ฉบับ '+saved.version;let p=editContext?.published;$('edit_status').textContent=p?'ฉบับที่แชทใช้: '+p.revision+' • ร่างล่าสุด: '+saved.version:'รายการนี้ยังไม่มีฉบับเผยแพร่ในฐานกลาง';$('edit_timing').textContent=['rate','rental_package','policy','competition_rule','competition','schedule','closure','news'].includes(record.kind)?'ถ้ามีวันเริ่มใช้ใหม่ ให้ปรับ “ข้อมูลนี้เริ่มใช้เมื่อไหร่?” ตามประกาศจริง ราคาหรือกฎที่เริ่มในอนาคตบันทึกเป็นร่างได้ แต่ยังไม่มีการเผยแพร่อัตโนมัติตามเวลา ต้องกดเผยแพร่เมื่อถึงวันเริ่มใช้':'แก้ชื่อหรือรายละเอียดได้โดยใช้รายการเดิม ถ้าเปลี่ยนเป็นอีกเกม อีกบริการ หรืออีกกลุ่มราคา ให้สร้างรายการใหม่';$('save').textContent='บันทึกเป็นฉบับร่างใหม่';}
function comparable(f){return {status:f?.status||'unknown',value:f?.status==='known'?f.value:null,note:f?.note||''};}
function stableValue(v){if(Array.isArray(v))return v.map(stableValue);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,stableValue(v[k])]));return v;}
function sameContent(a,b,key){let normalize=v=>{if(key==='validity'&&v){v={...v};for(let k of ['effective_from','effective_until'])if(v[k])v[k]=new Date(v[k]).toISOString();}return JSON.stringify(stableValue(v));};return normalize(a)===normalize(b);}
function recordChanges(a,b){let changes=[];for(let f of catalog[b.kind].fields){let old=comparable(a.fields[f.key]),next=comparable(b.fields[f.key]);if(!sameContent(old,next,f.key))changes.push({label:fieldLabel(f,b.kind),key:f.key,before:old,after:next,field:true});}for(let [key,label] of [['aliases','ชื่อที่ลูกค้าเรียก'],['validity','ช่วงวันที่มีผล']])if(!sameContent(a[key],b[key],key))changes.push({label,key,before:a[key],after:b[key]});let lang=r=>({source_language:r.localization.source_language,en_status:r.localization.en_status});if(!sameContent(lang(a),lang(b)))changes.push({label:'สถานะภาษา',key:'localization',before:lang(a),after:lang(b)});return changes;}
function readableChange(v,key,field=false){let root=node('div');if(field){let statusText={known:'มีข้อมูลยืนยัน',unknown:'ยังไม่ทราบ',not_applicable:'ไม่เกี่ยวข้อง',conflicted:'ข้อมูลขัดกัน'};root.append(node('strong',statusText[v.status]));if(v.status==='known')root.append(key==='amount_minor'?node('p',(v.value/100).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+' บาท'):exampleView(v.value));if(v.note)root.append(node('small','หมายเหตุ: '+v.note));}else if(key==='validity'){root.append(node('p',v.state==='known'?'ยืนยันช่วงวันที่แล้ว':'ยังไม่ยืนยันช่วงวันที่'));for(let [k,l] of [['effective_from','เริ่มใช้'],['effective_until','สิ้นสุด']])root.append(node('p',l+': '+(v[k]?new Date(v[k]).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})+' (เวลาไทย)':'ยังไม่กำหนด')));}else if(key==='localization'){root.append(node('p','ภาษาต้นทาง: '+({th:'ไทย',en:'อังกฤษ',mixed:'ทั้งสองภาษา'}[v.source_language]||v.source_language)),node('p','คำแปล: '+({missing:'ยังไม่มี',draft:'ร่าง',agent_translated:'แปลโดยระบบ',reviewed:'ตรวจแล้ว',stale:'ต้องตรวจใหม่'}[v.en_status]||v.en_status)));}else root.append(exampleView(v));return root;}
function showComparison(a,b,host,caption){host.replaceChildren();host.append(node('h3',caption));let changes=recordChanges(a,b);if(!changes.length){host.append(node('p','ยังไม่มีเนื้อหาที่เปลี่ยนจากฉบับที่ใช้เปรียบเทียบ'));return;}let table=node('table');table.className='changes-table';let head=node('tr');['ช่องที่เปลี่ยน','ก่อนแก้','หลังแก้'].forEach(t=>head.append(node('th',t)));table.append(head);for(let c of changes){let row=node('tr'),old=node('td'),next=node('td');old.append(readableChange(c.before,c.key,c.field));next.append(readableChange(c.after,c.key,c.field));row.append(node('th',c.label),old,next);table.append(row);}let wrap=node('div');wrap.className='table-scroll';wrap.append(table);host.append(wrap);}
$('compare_changes').onclick=()=>task(async()=>{if(!saved)return;let base=editContext?.published||record;showComparison(base,collect(),$('change_summary'),'เปรียบเทียบกับ '+(editContext?.published?'ฉบับที่แชทใช้ '+base.revision:'ร่างที่เปิดมา '+saved.version));});
$('edit_existing').onclick=()=>{message('เลือกหมวดทางซ้าย แล้วค้นหาชื่อหรือเลือกปุ่ม “✎ แก้ไข…” ของรายการเดิมด้านล่าง');$('search').focus();};
$('change_note').addEventListener('input',()=>dirty=true);
$('view_history').onclick=()=>task(async()=>{if(!saved)return;let x=await api('/api/edit-context?id='+encodeURIComponent(saved.record_id));let d=node('dialog');d.className='history-dialog';let close=node('button','ปิดประวัติ');close.onclick=()=>{d.close();d.remove();};d.append(node('h2','ประวัติข้อมูลเดิม (ดูอย่างเดียว)'),node('p','แสดงล่าสุด '+x.history.length+' จาก '+x.total_revisions+' ฉบับ ประวัติเก่ายังอยู่ในฐานข้อมูล การเปิดดูไม่เปลี่ยนข้อมูลในแชท'),close);let list=node('div'),view=node('div');for(let h of x.history){let line=node('div');line.className='history-row';let btn=node('button','ดูฉบับ '+h.version+(h.published?' • แชทใช้อยู่':''));let info=node('p',new Date(h.at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})+' เวลาไทย • ผู้แก้: '+h.actor+(h.change_note?' • เหตุผล: '+h.change_note:''));btn.onclick=async()=>{btn.disabled=true;try{let v=await api('/api/revision?id='+encodeURIComponent(saved.record_id)+'&version='+h.version);view.replaceChildren();view.append(node('h3','ข้อมูลในฉบับ '+h.version),node('p','ดูอย่างเดียว — ไม่ได้คืนค่าหรือเผยแพร่ฉบับนี้'));for(let f of catalog[v.record.kind].fields){let section=node('div');section.className='history-field';section.append(node('h4',fieldLabel(f,v.record.kind)),readableChange(comparable(v.record.fields[f.key]),f.key,true));view.append(section);}view.append(node('h4','ช่วงวันที่มีผล'),readableChange(v.record.validity,'validity'));}catch(e){view.replaceChildren(node('p',userError(e.message)));}finally{btn.disabled=false;}};line.append(btn,info);list.append(line);}d.append(list,view);d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();});
